CREATE TABLE "MarketingCampaign" ("id" TEXT NOT NULL, "organisationId" TEXT NOT NULL, "facilityId" TEXT NOT NULL, "name" TEXT NOT NULL, "source" TEXT NOT NULL, "medium" TEXT NOT NULL, "budget" DECIMAL(12,2) NOT NULL, "status" TEXT NOT NULL DEFAULT 'PLANNED', "version" INTEGER NOT NULL DEFAULT 1, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MarketingCampaign_pkey" PRIMARY KEY ("id"), CONSTRAINT "MarketingCampaign_facilityId_fkey" FOREIGN KEY ("facilityId") REFERENCES "Facility"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "MarketingCampaign_organisationId_fkey" FOREIGN KEY ("organisationId") REFERENCES "Organisation"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "MarketingLink" ("id" TEXT NOT NULL, "campaignId" TEXT NOT NULL, "label" TEXT NOT NULL, "landingPage" TEXT NOT NULL, "keyword" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MarketingLink_pkey" PRIMARY KEY ("id"), CONSTRAINT "MarketingLink_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "MarketingCampaign"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "MarketingActivity" ("id" TEXT NOT NULL, "campaignId" TEXT NOT NULL, "title" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "kind" TEXT NOT NULL, "occurredAt" TIMESTAMP(3) NOT NULL, "spend" DECIMAL(12,2) NOT NULL, "impressions" INTEGER NOT NULL DEFAULT 0, "clicks" INTEGER NOT NULL DEFAULT 0, "notes" TEXT, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MarketingActivity_pkey" PRIMARY KEY ("id"), CONSTRAINT "MarketingActivity_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "MarketingCampaign"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "MarketingCampaign_organisationId_facilityId_createdAt_idx" ON "MarketingCampaign"("organisationId", "facilityId", "createdAt");
CREATE INDEX "MarketingLink_campaignId_idx" ON "MarketingLink"("campaignId");
CREATE INDEX "MarketingActivity_campaignId_occurredAt_idx" ON "MarketingActivity"("campaignId", "occurredAt");
